func (this *Composite) computeSizeInPixels_(hintInPoints *Point, zoom int32, changed bool) *Point {
	this.display.RunSkin()
	var sizeInPoints *Point
	if this.layout != (nil) {
		if hintInPoints.X == DEFAULT || hintInPoints.Y == DEFAULT {
			changed = changed || (this.state&WidgetLAYOUT_CHANGED) != 0
			this.state &= ^WidgetLAYOUT_CHANGED
			sizeInPoints = this.layout.impl.computeSize_(this, hintInPoints.X, hintInPoints.Y, changed)
		} else {
			sizeInPoints = hintInPoints
		}
	} else {
		sizeInPoints = this.impl.minimumSize_(hintInPoints, changed)
		if sizeInPoints.X == 0 {
			sizeInPoints.X = WidgetDEFAULT_WIDTH
		}
		if sizeInPoints.Y == 0 {
			sizeInPoints.Y = WidgetDEFAULT_HEIGHT
		}
	}
	if hintInPoints.X != DEFAULT {
		sizeInPoints.X = hintInPoints.X
	}
	if hintInPoints.Y != DEFAULT {
		sizeInPoints.Y = hintInPoints.Y
	}
	var trim *Rectangle = Win32DPIUtilsPointToPixelWithSufficientlyLargeSize(this.impl.computeTrim_(0, 0, sizeInPoints.X, sizeInPoints.Y), this.impl.getAutoscalingZoom_())
	return NewPoint(trim.Width, trim.Height)
}

func (this *Composite) computeTabList_() []*Widget {
	var result []*Widget = this.Scrollable.computeTabList_()
	if int32(len(result)) == 0 {
		return result
	}
	var list []*Control
	if this.tabList != (nil) {
		list = this._getTabList()
	} else {
		list = this._getChildren()
	}
	for _, child := range list {
		var childList []*Widget = child.impl.computeTabList_()
		if int32(len(childList)) != 0 {
			var newResult []*Widget = make([]*Widget, int32(len(result))+int32(len(childList)))
			copy(newResult[0:], result[0:0+int32(len(result))])
			copy(newResult[int32(len(result)):], childList[0:0+int32(len(childList))])
			result = newResult
		}
	}
	return result
}

func (this *Composite) CopyArea(gcLike GCLike, x int32, y int32, width int32, height int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	this.CheckWidget()
	if gc == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if gc.impl.isDisposed_() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var hDC int64 = gc.Handle
	var nSavedDC int32 = win32.OSSaveDC(hDC)
	win32.OSIntersectClipRect(hDC, 0, 0, width, height)
	var lpPoint *win32.POINT = win32.NewPOINT()
	var hwndParent int64 = win32.OSGetParent(this.Handle)
	win32.OSMapWindowPoints(this.Handle, hwndParent, lpPoint, 1)
	var rect *win32.RECT = win32.NewRECT()
	win32.OSGetWindowRect(this.Handle, rect)
	var lpPoint1 *win32.POINT = win32.NewPOINT()
	var lpPoint2 *win32.POINT = win32.NewPOINT()
	x = x + (lpPoint.X - rect.Left)
	y = y + (lpPoint.Y - rect.Top)
	win32.OSSetWindowOrgEx(hDC, x, y, lpPoint1)
	win32.OSSetBrushOrgEx(hDC, x, y, lpPoint2)
	var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_STYLE)
	if (bits & win32.OSWS_VISIBLE) == 0 {
		win32.OSDefWindowProc(this.Handle, win32.OSWM_SETREDRAW, int64(1), int64(0))
	}
	win32.OSRedrawWindow(this.Handle, nil, int64(0), win32.OSRDW_UPDATENOW|win32.OSRDW_ALLCHILDREN)
	win32.OSPrintWindow(this.Handle, hDC, 0)
	if (bits & win32.OSWS_VISIBLE) == 0 {
		win32.OSDefWindowProc(this.Handle, win32.OSWM_SETREDRAW, int64(0), int64(0))
	}
	win32.OSRestoreDC(hDC, nSavedDC)
}

func (this *Composite) createHandle_() {
	this.Scrollable.createHandle_()
	this.state |= WidgetCANVAS
	if (this.style&(H_SCROLL|V_SCROLL)) == 0 || this.impl.findThemeControl_() == upcastCompositeToControl(this.parent) {
		this.state |= WidgetTHEME_BACKGROUND
	}
	if (this.style & TRANSPARENT) != 0 {
		var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_EXSTYLE)
		bits |= win32.OSWS_EX_TRANSPARENT
		win32.OSSetWindowLong(this.Handle, win32.OSGWL_EXSTYLE, bits)
	}
}

func (this *Composite) DrawBackground(gcLike GCLike, x int32, y int32, width int32, height int32, offsetX int32, offsetY int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	this.CheckWidget()
	var zoom int32 = this.impl.getAutoscalingZoom_()
	var rectangle *Rectangle = Win32DPIUtilsPointToPixelOverload6(NewRectangle(x, y, width, height), zoom)
	offsetX = DPIUtilPointToPixel(offsetX, zoom)
	offsetY = DPIUtilPointToPixel(offsetY, zoom)
	this.DrawBackgroundInPixels(gc, rectangle.X, rectangle.Y, rectangle.Width, rectangle.Height, offsetX, offsetY)
}

func (this *Composite) DrawBackgroundInPixels(gcLike GCLike, x int32, y int32, width int32, height int32, offsetX int32, offsetY int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	if gc == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if gc.impl.isDisposed_() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var rect *win32.RECT = win32.NewRECT()
	win32.OSSetRect(rect, x, y, x+width, y+height)
	var hDC int64 = gc.Handle
	var pixel int32
	if this.background == -1 {
		pixel = gc.GetBackground().Handle
	} else {
		pixel = -1
	}
	this.DrawBackgroundHDCRectPixelTxTy(hDC, rect, pixel, offsetX, offsetY)
}

