func (this *Composite) findDeferredControl_() *Composite {
	var cond151 *Composite
	if this.layoutCount > 0 {
		cond151 = this
	} else {
		cond151 = this.parent.impl.findDeferredControl_()
	}
	return cond151
}

func (this *Composite) findMenus_(control *Control) []*Menu {
	if control == upcastCompositeToControl(this) {
		return make([]*Menu, 0)
	}
	var result []*Menu = this.Scrollable.findMenus_(control)
	for _, child := range this._getChildren() {
		var menuList []*Menu = child.impl.findMenus_(control)
		if int32(len(menuList)) != 0 {
			var newResult []*Menu = make([]*Menu, int32(len(result))+int32(len(menuList)))
			copy(newResult[0:], result[0:0+int32(len(result))])
			copy(newResult[int32(len(result)):], menuList[0:0+int32(len(menuList))])
			result = newResult
		}
	}
	return result
}

func (this *Composite) fixChildren_(newShell *Shell, oldShell *Shell, newDecorations *Decorations, oldDecorations *Decorations, menus []*Menu) {
	this.Scrollable.fixChildren_(newShell, oldShell, newDecorations, oldDecorations, menus)
	for _, child := range this._getChildren() {
		child.impl.fixChildren_(newShell, oldShell, newDecorations, oldDecorations, menus)
	}
}

func (this *Composite) FixTabList(controlLike ControlLike) {
	var control *Control
	if controlLike != nil {
		control = controlLike.AsControl()
	}
	_ = control
	if this.tabList == (nil) {
		return
	}
	var count int32 = 0
	for _, element := range this.tabList {
		if element == control {
			count++
		}
	}
	if count == 0 {
		return
	}
	var newList []*Control = nil
	var length int32 = int32(len(this.tabList)) - count
	if length != 0 {
		newList = make([]*Control, length)
		var index int32 = 0
		for _, element := range this.tabList {
			if element != control {
				t152 := index
				index++
				newList[t152] = element
			}
		}
	}
	this.tabList = newList
}

